import torch
import torch_npu
import custom_ops_lib

class ModelNew(torch.nn.Module):
    def __init__(self, embed_dim, num_heads):
        super().__init__()
        self.attn = torch.nn.MultiheadAttention(embed_dim, num_heads)
        self.norm = torch.nn.LayerNorm(embed_dim)

    def forward(self, x):
        B, C, H, W = x.shape
        x_seq = x.view(B, C, H * W).permute(2, 0, 1)  # (seq_len, batch_size, embed_dim)
        attn_output, _ = self.attn(x_seq, x_seq, x_seq)
        summed = custom_ops_lib.vision_attention_custom(attn_output, x_seq)
        out = self.norm(summed)
        out = out.permute(1, 2, 0).view(B, C, H, W)
        return out
